import pytest
from typing import Annotated
from fastapi import FastAPI, Depends, Response
from fastapi.testclient import TestClient

def modify_response():
    return Response(content="modified", media_type="text/plain")

def test_response_dependency_annotated():
    app = FastAPI()

    @app.get("/")
    def endpoint(response: Annotated[Response, Depends(modify_response)]):
        return {"message": "ok"}

    client = TestClient(app)
    response = client.get("/")
    assert response.status_code == 200
    # Note: the modify_response returns a Response object, but FastAPI's 
    # dependency injection for Response is a bit special. 
    # If the dependency returns a Response, it should be used as the response.
    # However, in the endpoint, we are returning {"message": "ok"}.
    # Let's see what happens.
    # Actually, if a dependency returns a Response, FastAPI uses it.
    # Wait, if the endpoint also returns something, which one wins?
    # Usually the endpoint return value wins unless the dependency raises an exception or 
    # specifically modifies the response object.
    # In FastAPI, if you inject `response: Response`, you can modify it.
    # If you use `Depends(modify_response)`, and `modify_response` returns a `Response` object,
    # it's just a value injected into the parameter.
    # To actually modify the response, `modify_response` should probably take `response: Response` as an argument.

def test_response_dependency_default():
    app = FastAPI()

    @app.get("/")
    def endpoint(response: Response = Depends(modify_response)):
        return {"message": "ok"}

    client = TestClient(app)
    response = client.get("/")
    assert response.status_code == 200

def test_response_regular_injection():
    app = FastAPI()

    @app.get("/")
    def endpoint(response: Response):
        response.headers["X-Custom"] = "value"
        return {"message": "ok"}

    client = TestClient(app)
    response = client.get("/")
    assert response.headers["X-Custom"] == "value"
    assert response.status_code == 200

